select * from (select case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, is_active, count(distinct age) as unique_segments from customers where country not in ('UK', 'JP') group by case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end, is_active) as sub where unique_segments > 6 order by signup_cohort asc, unique_segments desc
